import{_ as i,a0 as c,w as _,s as g,ao as s,I as a,x as t,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"如何使用Aptik來備份和恢復Ubuntu中的Apps和PPAs | LCTT x X-CMD","titleTemplate":false,"description":"如何使用Aptik來備份和恢復Ubuntu中的Apps和PPAs | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用Aptik來備份和恢復Ubuntu中的Apps和PPAs | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用Aptik來備份和恢復Ubuntu中的Apps和PPAs | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20100105 How to Backup and Restore Your Apps and PPAs in Ubuntu Using Aptik","title":"如何使用Aptik來備份和恢復Ubuntu中的Apps和PPAs","tag":"201501","desc":""},"relativePath":"201501/20100105 How to Backup and Restore Your Apps and PPAs in Ubuntu Using Aptik.md","filePath":"[post].md"}'),d={name:"201501/20100105 How to Backup and Restore Your Apps and PPAs in Ubuntu Using Aptik.md"};function r(u,p,l,k,m,w){const e=c("Link");return _(),g("div",null,[p[14]||(p[14]=s(`<h1 id="如何使用aptik來備份和恢復ubuntu中的apps和ppas" tabindex="-1">如何使用Aptik來備份和恢復Ubuntu中的Apps和PPAs <a class="header-anchor" href="#如何使用aptik來備份和恢復ubuntu中的apps和ppas" aria-label="Permalink to “如何使用Aptik來備份和恢復Ubuntu中的Apps和PPAs”">​</a></h1><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x300x00_lead_image_aptik.png.pagespeed.ic.n3TJwp8YK_.png" alt="00_lead_image_aptik"></p><p>當你想重裝Ubuntu或者僅僅是想安裝它的一個新版本的時候，如果有個便捷的方法來重新安裝之前的應用並且重置其設置會很方便的。此時 <em>Aptik</em> 粉墨登場，它可以幫助你輕鬆實現。</p><p>Aptik（自動包備份和恢復）是一個可以用在Ubuntu，Linux Mint 和其他基於Debian以及Ubuntu的Linux發行版上的應用，它允許你將已經安裝過的包括軟件庫、下載包、安裝的應用和主題、用户設置在內的PPAs(個人軟件包存檔)備份到外部的U盤、網絡存儲或者類似於Dropbox的雲服務上。</p><p>注意：當我們在此文章中説到輸入某些東西的時候，如果被輸入的內容被引號包裹，請不要將引號一起輸入進去，除非我們有特殊説明。</p><p>想要安裝Aptik，需要先添加其PPA。使用Ctrl + Alt + T快捷鍵打開一個新的終端窗口。輸入以下文字，並按回車執行。</p><pre><code>sudo apt-add-repository –y ppa:teejee2008/ppa
</code></pre><p>當提示輸入密碼的時候，輸入你的密碼然後按回車。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x99x01_command_to_add_repository.png.pagespeed.ic.UfVC9QLj54.png" alt="01_command_to_add_repository"></p><p>在命令列提示符輸入下邊的命令，來確保資源庫已經是最新版本。</p><pre><code>sudo apt-get update
</code></pre><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x252x02_update_command.png.pagespeed.ic.m9pvd88WNx.png" alt="02_update_command"></p><p>更新完畢後，你就完成了安裝Aptik的準備工作。接下來輸入以下命令並按回車：</p><pre><code>sudo apt-get install aptik
</code></pre><p>注意：你可能會看到一些有關於獲取不到包更新的錯誤提示。不過別擔心，如果這些提示看起來跟下邊圖片中類似的話，你的Aptik的安裝就沒有任何問題。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x416x03_command_to_install_aptik.png.pagespeed.ic.1jtHysRO9h.png" alt="03_command_to_install_aptik"></p><p>安裝過程會被顯示出來。其中一個被顯示出來的消息會提到此次安裝會使用掉多少磁盤空間，然後提示你是否要繼續，按下“y”再按回車，繼續安裝。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x416x04_do_you_want_to_continue.png.pagespeed.ic.WQ15_UxK5Z.png" alt="04_do_you_want_to_continue"></p><p>當安裝完成後，輸入“Exit”並按回車或者按下左上角的“X”按鈕，關閉終端窗口。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x416x05_closing_terminal_window.png.pagespeed.ic.9QoqwM7Mfr.png" alt="05_closing_terminal_window"></p><p>在正式運行Aptik前，你需要設置好備份目錄到一個U盤、網絡驅動器或者類似於Dropbox和Google Drive的雲帳號上。這兒的例子中，我們使用的是Dropbox。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x243x06_creating_backup_folder.png.pagespeed.ic.7HzR9KwAfQ.png" alt="06_creating_backup_folder"></p><p>一旦設置好備份目錄，點擊啓動欄上方的“Search”按鈕。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x177x07_opening_search.png.pagespeed.ic.qvFiw6_sXa.png" alt="07_opening_search"></p><p>在搜索框中鍵入 “aptik”。結果會隨着你的輸入顯示出來。當Aptik圖標顯示出來的時候，點擊它打開應用。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x338x08_starting_aptik.png.pagespeed.ic.8fSl4tYR0n.png" alt="08_starting_aptik"></p><p>此時一個對話框會顯示出來要求你輸入密碼。輸入你的密碼並按“OK”按鈕。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x337x09_entering_password.png.pagespeed.ic.yanJYFyP1i.png" alt="09_entering_password"></p><p>Aptik的主窗口顯示出來了。從“Backup Directory”下拉列表中選擇“Other…”。這個操作允許你選擇你已經建立好的備份目錄。</p><p>注意：在下拉列表的右側的 “Open” 按鈕會在一個文件管理窗口中打開選擇目錄功能。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x533x10_selecting_other_for_directory.png.pagespeed.ic.dHbmYdAHYx.png" alt="10_selecting_other_for_directory"></p><p>在 “Backup Directory” 對話窗口中，定位到你的備份目錄，然後按“Open”。</p><p>注意：如果此時你尚未建立備份目錄或者想在備份目錄中新建個子目錄，你可以點“Create Folder”來新建目錄。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x470x11_choosing_directory.png.pagespeed.ic.E-56x54cy9.png" alt="11_choosing_directory"></p><p>點擊“Software Sources (PPAs).”右側的 “Backup”來備份已安裝的PPAs。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x13_selecting_all_software_sources.png.pagespeed.ic.zDFiDGfnks.png" alt="12_clicking_backup_software_sources"></p><p>然後“Backup Software Sources”對話窗口顯示出來。已安裝的包和對應的源（PPA）同時也顯示出來了。選擇你需要備份的源（PPAs），或者點“Select All”按鈕選擇所有源。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x13_selecting_all_software_sources.png.pagespeed.ic.zDFiDGfnks.png" alt="13_selecting_all_software_sources"></p><p>點擊 “Backup” 開始備份。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x14_clicking_backup_for_all_software_sources.png.pagespeed.ic.n5h_KnQVZa.png" alt="14_clicking_backup_for_all_software_sources"></p><p>備份完成後，一個提示你備份完成的對話窗口會蹦出來。點擊 “OK” 關掉。</p><p>一個名為“ppa.list”的文件出現在了備份目錄中。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x15_closing_finished_dialog_software_sources.png.pagespeed.ic.V25-KgSXdY.png" alt="15_closing_finished_dialog_software_sources"></p><p>接下來，“Downloaded Packages (APT Cache)”的項目只對重裝同樣版本的Ubuntu有用處。它會備份下你係統緩存(/var/cache/apt/archives)中的包。如果你是升級系統的話，可以跳過這個條目，因為針對新系統的包會比現有系統緩存中的包更加新一些。</p><p>備份和恢復下載過的包，這可以在重裝Ubuntu，並且重裝包的時候節省時間和網絡帶寬。因為一旦你把這些包恢復到系統緩存中之後，他們可以重新被利用起來，這樣下載過程就免了，包的安裝會更加快捷。</p><p>如果你是重裝相同版本的Ubuntu系統的話，點擊 “Downloaded Packages (APT Cache)” 右側的 “Backup” 按鈕來備份系統緩存中的包。</p><p>注意：當你備份下載過的包的時候是沒有二級對話框出現的。你係統緩存 (/var/cache/apt/archives) 中的包會被拷貝到備份目錄下一個名叫 “archives” 的文件夾中，當整個過程完成後會出現一個對話框來告訴你備份已經完成。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x544x16_downloaded_packages_backed_up.png.pagespeed.ic.z8ysuwzQAK.png" alt="16_downloaded_packages_backed_up"></p><p>有一些包是你的Ubuntu發行版的一部分。因為安裝Ubuntu系統的時候會自動安裝它們，所以它們是不會被備份下來的。例如，火狐瀏覽器在Ubuntu和其他類似Linux發行版上都是默認被安裝的，所以默認情況下，它不會被選擇備份。</p>`,49)),a("p",null,[p[1]||(p[1]=t("像",-1)),o(e,{href:"http://www.howtogeek.com/203768"},{default:n(()=>[...p[0]||(p[0]=[t("package for the Chrome web browser",-1)])]),_:1}),p[2]||(p[2]=t("這種系統安裝完後才安裝的包或者包含 Aptik 的包會默認被選擇上。這可以方便你備份這些後安裝的包。",-1))]),p[15]||(p[15]=s('<p>按照需要選擇想要備份的包。點擊 “Software Selections” 右側的 “Backup” 按鈕備份頂層包。</p><p>注意：依賴包不會出現在這個備份中。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x18_clicking_backup_for_software_selections.png.pagespeed.ic.QI5D-IgnP_.png" alt="18_clicking_backup_for_software_selections"></p><p>備份目錄中出現了兩個名為 “packages.list” 和“packages-installed.list” 的文件，並且會彈出一個通知你備份完成的對話框。點擊 ”OK“關閉它。</p><p>注意：“packages-installed.list”文件包含了所有的包，而 “packages.list” 在包含了所有包的前提下還指出了那些包被選擇上了。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x19_software_selections_backed_up.png.pagespeed.ic.LVmgs6MKPL.png" alt="19_software_selections_backed_up"></p><p>要備份已安裝軟件的設置的話，點擊 Aptik 主界面 “Application Settings” 右側的 “Backup” 按鈕，選擇你要備份的設置，點擊“Backup”。</p><p>注意：如果你要選擇所有設置，點擊“Select All”按鈕。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x20_backing_up_app_settings.png.pagespeed.ic.7_kgU3Dj_m.png" alt="20_backing_up_app_settings"></p><p>被選擇的配置文件統一被打包到一個名叫 “app-settings.tar.gz” 的文件中。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x21_zipping_settings_files.png.pagespeed.ic.dgoBj7egqv.png" alt="21_zipping_settings_files"></p><p>當打包完成後，打包後的文件被拷貝到備份目錄下，另外一個備份成功的對話框出現。點擊“OK”關掉。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x22_app_settings_backed_up.png.pagespeed.ic.Mb6utyLJ3W.png" alt="22_app_settings_backed_up"></p><p>放在 “/usr/share/themes” 目錄的主題和放在 “/usr/share/icons” 目錄的圖標也可以備份。點擊 “Themes and Icons” 右側的 “Backup” 來進行此操作。“Backup Themes” 對話框默認選擇了所有的主題和圖標。你可以安裝需要的、取消一些不要的，然後點擊 “Backup” 進行備份。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x22a_backing_up_themes_and_icons.png.pagespeed.ic.KXa8W3YhyF.png" alt="22a_backing_up_themes_and_icons"></p><p>主題被打包拷貝到備份目錄下的 “themes” 文件夾中，圖標被打包拷貝到備份目錄下的 “icons” 文件夾中。然後成功提示對話框出現，點擊“OK”關閉它。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x530x22b_themes_and_icons_backed_up.png.pagespeed.ic.ejjRaymD39.png" alt="22b_themes_and_icons_backed_up"></p><p>一旦你完成了需要的備份，點擊主界面左上角的“X”關閉 Aptik 。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x542x23_closing_aptik.png.pagespeed.ic.pNk9Vt3--l.png" alt="23_closing_aptik"></p><p>備份過的文件已存在於你選擇的備份目錄中，可以隨時查看。</p><p><img src="http://cdn5.howtogeek.com/wp-content/uploads/2014/12/650x374x24_backup_files_in_directory.png.pagespeed.ic.vwblOfN915.png" alt="24_backup_files_in_directory"></p><p>當你重裝Ubuntu或者安裝新版本的Ubuntu後，在新的系統中安裝 Aptik 並且將備份好的文件置於新系統中使用。運行 Aptik，並使用每個條目的 “Restore” 按鈕來恢復你的軟件源、應用、包、設置、主題以及圖標。</p><hr>',23)),a("p",null,[p[4]||(p[4]=t("via: ",-1)),o(e,{href:"http://www.howtogeek.com/206454/how-to-backup-and-restore-your-apps-and-ppas-in-ubuntu-using-aptik/"},{default:n(()=>[...p[3]||(p[3]=[t("http://www.howtogeek.com/206454/how-to-backup-and-restore-your-apps-and-ppas-in-ubuntu-using-aptik/",-1)])]),_:1})]),a("p",null,[p[7]||(p[7]=t("作者：Lori Kaufman 譯者：",-1)),o(e,{href:"https://github.com/mr-ping"},{default:n(()=>[...p[5]||(p[5]=[t("Ping",-1)])]),_:1}),p[8]||(p[8]=t(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:n(()=>[...p[6]||(p[6]=[t("wxy",-1)])]),_:1})]),a("p",null,[p[11]||(p[11]=t("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...p[9]||(p[9]=[t("LCTT",-1)])]),_:1}),p[12]||(p[12]=t(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:n(()=>[...p[10]||(p[10]=[t("Linux中國",-1)])]),_:1}),p[13]||(p[13]=t(" 榮譽推出",-1))])])}const b=i(d,[["render",r]]);export{A as __pageData,b as default};
